import { motion, useInView } from "framer-motion";
import { useRef } from "react";
import { Github, ExternalLink } from "lucide-react";

const projects = [
  {
    title: " Full-Stack E-Commerce Platform",
    description: "Full-stack e-commerce app with React, Node.js, and MongoDB featuring user authentication, product management, and payment integration.",
    tech: ["React", "Node.js", "MongoDB", "Express.js"],
    github: "https://github.com",
    live: "https://cosmoshoponline.netlify.app/"
  },
  {
    title: "Myntra Clone",
    description: "Desktop application for managing student records, attendance, and grades built with Java and MySQL.",
    tech: ["HTML", "CSS", "J"],
    github: "https://github.com",
    live: ""
  },
  {
    title: "Weather Dashboard",
    description: "Real-time weather application using OpenWeather API with location search and 7-day forecast display.",
    tech: ["React", "API", "CSS"],
    github: "https://github.com",
    live: "https://demo.com"
  },
  {
    title: "Task Management App",
    description: "Productivity app with drag-and-drop kanban boards, user authentication, and real-time updates.",
    tech: ["React", "Firebase", "Tailwind"],
    github: "https://github.com",
    live: "https://demo.com"
  }
];

const Projects = () => {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-50px" });

  return (
    <section id="projects" className="projects-section" ref={ref}>
      <motion.h2
        initial={{ opacity: 0, y: 30 }}
        animate={isInView ? { opacity: 1, y: 0 } : {}}
        transition={{ duration: 0.6 }}
      >
        My Projects
      </motion.h2>

      <div className="projects-grid">
        {projects.map((project, index) => (
          <motion.div
            key={project.title}
            initial={{ opacity: 0, y: 50, scale: 0.9 }}
            animate={isInView ? { opacity: 1, y: 0, scale: 1 } : {}}
            transition={{ duration: 0.5, delay: index * 0.1 }}
            whileHover={{ y: -15 }}
            className="project-card"
          >
            <motion.div
              initial={{ opacity: 0 }}
              animate={isInView ? { opacity: 1 } : {}}
              transition={{ delay: index * 0.1 + 0.3 }}
              className="project-content"
            >
              <motion.h3
                whileHover={{ color: "#6366f1" }}
                transition={{ duration: 0.3 }}
              >
                {project.title}
              </motion.h3>
              <p>{project.description}</p>
              <div className="project-tech">
                {project.tech.map((t, i) => (
                  <motion.span
                    key={t}
                    className="tech-tag"
                    initial={{ opacity: 0, x: -20 }}
                    animate={isInView ? { opacity: 1, x: 0 } : {}}
                    transition={{ delay: index * 0.1 + i * 0.05 + 0.2 }}
                    whileHover={{ scale: 1.1, backgroundColor: "#06b6d4", color: "#0a0a0f" }}
                  >
                    {t}
                  </motion.span>
                ))}
              </div>
              <div className="project-links">
                <motion.a
                  href={project.github}
                  target="_blank"
                  rel="noreferrer"
                  whileHover={{ x: 5 }}
                  whileTap={{ scale: 0.95 }}
                >
                  <Github size={20} /> Code
                </motion.a>
                {project.live && (
                  <motion.a
                    href={project.live}
                    target="_blank"
                    rel="noreferrer"
                    whileHover={{ x: 5 }}
                    whileTap={{ scale: 0.95 }}
                  >
                    <ExternalLink size={20} /> Demo
                  </motion.a>
                )}
              </div>
            </motion.div>
          </motion.div>
        ))}
      </div>
    </section>
  );
};

export default Projects;
